package org.tentackle.preferenzr.client;

import javafx.stage.Stage;
import javafx.stage.WindowEvent;

import org.tentackle.misc.Identifiable;
import org.tentackle.preferenzr.common.Version;
import org.tentackle.preferenzr.gui.GuiBundle;
import org.tentackle.preferenzr.gui.main.MainController;
import org.tentackle.fx.rdc.app.DesktopApplication;
import org.tentackle.fx.rdc.app.FxApplication;
import org.tentackle.pdo.DomainContext;
import org.tentackle.pdo.PersistentDomainObject;
import org.tentackle.security.SecurityFactory;
import org.tentackle.session.ModificationTracker;

/**
 * The Preferenzr application.
 */
public class PreferenzrFxClient extends DesktopApplication<MainController> {

  /**
   * Creates the application.
   * <p>
   * Preferenzr is a non-typical Tentackle application:
   * <ul>
   * <li>single connection (usually directly via JDBC)</li>
   * <li>no modification tracker and no caching</li>
   * <li>disabled security managar</li>
   * <li>database access only to the tables <code>preference</code>, <code>preferencekey</code>, <code>modification</code>
   * and the <code>object_sequence_id</code>.
   * Allows to access the database as a user with limited privileges.</li>
   * </ul>
   */
  public PreferenzrFxClient() {
    super("Preferenzr", Version.RELEASE);
  }

  @Override
  protected void configureModificationTracker() {
    // no modification tracker at all
    getProperties().put(DISABLE_MODIFICATION_TRACKER, "");
    ModificationTracker.getInstance().setSession(getSession());   // but session must be set to persist the preference data
  }

  @Override
  protected void configureSecurityManager() {
    // no security manager
    SecurityFactory.getInstance().getSecurityManager().setEnabled(false);
  }

  @Override
  public Class<? extends FxApplication> getApplicationClass() {
    return PreferenzrLoginApplication.class;
  }

  @Override
  public Class<MainController> getMainControllerClass() {
    return MainController.class;
  }

  @Override
  public void configureMainStage(Stage mainStage) {
    showApplicationStatus(GuiBundle.getString("initialize GUI..."), 0.9);
    super.configureMainStage(mainStage);
    mainStage.setTitle("Preferenzr");
    mainStage.setOnCloseRequest((WindowEvent ev) -> {
      ev.consume();
      getMainController().exit();
    });
  }

  @Override
  public <U extends Identifiable> U getUser(DomainContext context, long userId) {
    return null;    // no users, security manager disabled
  }

  @Override
  public void classMapped(String name, Class<?> clazz) {
    // not needed
  }

  /**
   * Starts the FX client application.
   *
   * @param args the command line arguments
   */
  public static void main(String[] args) {
    new PreferenzrFxClient().start(args);
  }

}
